export const getLootsControllerFetchLootsByGuildIdUrl = ({ guildId }: LootsControllerFetchLootsByGuildIdPathParameters,
    params?: LootsControllerFetchLootsByGuildIdParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    const explodeParameters = ["npcs","players","rarities","professions","npcTypes","itemNames"];

    if (Array.isArray(value) && explodeParameters.includes(key)) {
      value.forEach((v) => {
        normalizedParams.append(key, v === null ? 'null' : String(v));
      });
      return;
    }

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/guilds/${guildId}/loots?${stringifiedParams}` : `/guilds/${guildId}/loots`
}

