export const getEventsAssignmentControllerUnassignMemberUrl = ({ guildId, eventId, mapId }: EventsAssignmentControllerUnassignMemberPathParameters,
    params?: EventsAssignmentControllerUnassignMemberParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/guilds/${guildId}/events/${eventId}/maps/${mapId}/assign?${stringifiedParams}` : `/guilds/${guildId}/events/${eventId}/maps/${mapId}/assign`
}

